import{_ as a,o as n,a as p,b as c}from"./app.DKoEZOcr.js";const l="/ascendc.github.io/pr/5487/assets/cooperative_groups.DqVE5ZgC.png",g=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"SIMT协作组","link":"/guide/programming_guide/advanced_programming/simt_cooperative_groups"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/simt_cooperative_groups.md","filePath":"guide/programming_guide/advanced_programming/simt_cooperative_groups.md","outlineHeaders":[{"level":2,"title":"协作组使用方法","slug":"协作组使用方法","link":"#协作组使用方法"},{"level":2,"title":"协作组类型","slug":"协作组类型","link":"#协作组类型"},{"level":3,"title":"grid_group","slug":"grid_group","link":"#grid_group"},{"level":3,"title":"thread_block","slug":"thread_block","link":"#thread_block"},{"level":3,"title":"thread_block_tile","slug":"thread_block_tile","link":"#thread_block_tile"},{"level":3,"title":"coalesced_group","slug":"coalesced_group","link":"#coalesced_group"},{"level":2,"title":"组划分","slug":"组划分","link":"#组划分"},{"level":3,"title":"tiled_partition","slug":"tiled_partition","link":"#tiled_partition"},{"level":3,"title":"binary_partition","slug":"binary_partition","link":"#binary_partition"},{"level":2,"title":"注意事项","slug":"注意事项","link":"#注意事项"}],"lastUpdated":1787050286000}'),e={name:"guide/programming_guide/advanced_programming/simt_cooperative_groups.md"};function o(i,s,t,d,r,h){return n(),p("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>SIMT协作组简介</h1><p>协作组（cooperative_groups）是Ascend C SIMT编程模型的扩展，用于组织协作线程组。协作组使开发者能够控制线程协作的粒度，实现更丰富、更高效的并行处理逻辑。</p><p>Ascend C SIMT编程模型中仅提供<code>asc_syncthreads()</code>接口来实现线程块内所有线程的同步。当开发者希望以更细粒度的方式同步线程，从而实现更灵活的设计时，往往需要自行通过内存栅栏接口实现相应的同步逻辑。协作组提供安全可靠的机制，协助开发者实现灵活、高效的线程协作。</p><h2 id="协作组使用方法">协作组使用方法<a class="header-anchor" href="#协作组使用方法">​</a></h2><p>协作组中最重要的概念是使用一个对象表示一组线程，然后通过对象方法控制组内线程。对象可以明确表达开发者的意图，将协作组对象传递到某个函数可以清晰地表达“哪些线程必须共同调用该函数”。</p><p>协作组提供了自定义线程组的方法以及操作线程组的接口，全量的协作组API列表可在<a href="../../../api/SIMT-API/cooperative_groups/cooperative_groups.html">SIMT协作组API</a>中获取。使用协作组API时需要包含以下头文件，并使用协作组命名空间。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&lt;simt_api/cooperative_groups.h&gt;</span>

<span class="k">using</span><span class="w"> </span><span class="k">namespace</span><span class="w"> </span><span class="nn">cooperative_groups</span><span class="p">;</span>
<span class="c1">// 更推荐使用别名，避免污染全局命名空间</span>
<span class="k">namespace</span><span class="w"> </span><span class="nn">cg</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nn">cooperative_groups</span><span class="p">;</span>
</code></pre></div><h2 id="协作组类型">协作组类型<a class="header-anchor" href="#协作组类型">​</a></h2><p>协作组分为隐式组和显式组。隐式组与核函数（Kernel）中的代码无关，它代表的是核函数（Kernel）的启动配置，即创建了多少个线程块，每个线程块中有多少个线程来执行核函数（Kernel）。隐式组为划分出更细粒度的协作组提供了起点。显式组是在核函数（Kernel）中由开发者手动划分出的协作组。</p><p>当前提供以下协作组类型：</p><ul><li>隐式组： <ul><li><a href="../../../api/SIMT-API/cooperative_groups/grid_group/grid_group_intro.html">grid_group</a>：对当前Grid中所有SIMT线程的抽象，提供Grid级别的信息查询和跨线程块同步接口。</li><li><a href="../../../api/SIMT-API/cooperative_groups/thread_block/thread_block_intro.html">thread_block</a>：对线程块的抽象，提供线程块级别的线程管理和同步接口。</li></ul></li><li>显式组： <ul><li><a href="../../../api/SIMT-API/cooperative_groups/thread_block_tile/thread_block_tile_intro.html">thread_block_tile</a>：由父组划分得到的固定大小线程子组，支持组内同步、shfl类和vote类线程操作。</li><li><a href="../../../api/SIMT-API/cooperative_groups/coalesced_group/coalesced_group_intro.html">coalesced_group</a>：当前Warp内处于同一执行路径的活跃线程集合，常用于处理分支发散后的线程协作。</li></ul></li></ul><p><strong>图1</strong> 线程块中的协作组层次结构图</p><p><img src="`+l+`" alt="线程块中的协作组层次结构"></p><h3 id="grid_group">grid_group<a class="header-anchor" href="#grid_group">​</a></h3><p><code>grid_group</code>表示当前核函数（Kernel）启动的Grid协作组，覆盖Grid内所有线程块及其SIMT线程，通过<code>this_grid()</code>获取。它适合需要在多个线程块之间建立执行顺序的场景。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">grid_group</span><span class="w"> </span><span class="n">grid</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">this_grid</span><span class="p">();</span>
</code></pre></div><p><code>grid_group</code>提供Grid级别的信息查询能力和跨线程块的同步能力，例如：</p><ul><li><code>thread_rank()</code>：获取当前线程在Grid内所有SIMT线程中的线性rank。</li><li><code>block_rank()</code>：获取当前线程所属线程块在Grid内的线性rank。</li><li><code>num_threads()</code>：获取Grid内SIMT线程总数。</li><li><code>num_blocks()</code>：获取Grid内线程块总数。</li><li><code>sync()</code>：同步Grid内所有SIMT线程。</li></ul><p><code>grid_group</code>仅支持SIMT编程场景，不支持SIMD与SIMT混合编程场景。</p><h3 id="thread_block">thread_block<a class="header-anchor" href="#thread_block">​</a></h3><p><code>thread_block</code>表示当前线程所在的线程块，通过<code>this_thread_block()</code>获取。它是进一步划分子协作组的常用起点。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">thread_block</span><span class="w"> </span><span class="n">block</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">this_thread_block</span><span class="p">();</span>
</code></pre></div><p><code>thread_block</code>提供线程块级别的信息查询和同步能力，例如：</p><ul><li><code>thread_rank()</code>：获取当前线程在线程块内的线性rank。</li><li><code>thread_index()</code>：获取当前线程在线程块内的三维索引。</li><li><code>group_index()</code>：获取当前线程块在Grid中的三维索引。</li><li><code>sync()</code>：同步线程块内线程。</li></ul><h3 id="thread_block_tile">thread_block_tile<a class="header-anchor" href="#thread_block_tile">​</a></h3><p><code>thread_block_tile</code>表示由父组划分得到的固定大小线程子组。子组大小由模板参数指定，适合在编译期确定每个协作单元大小的场景。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">thread_block</span><span class="w"> </span><span class="n">block</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">this_thread_block</span><span class="p">();</span>
<span class="k">auto</span><span class="w"> </span><span class="n">tile4</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">tiled_partition</span><span class="o">&lt;</span><span class="mi">4</span><span class="o">&gt;</span><span class="p">(</span><span class="n">block</span><span class="p">);</span>
</code></pre></div><p><code>thread_block_tile</code>除支持<code>sync()</code>、<code>thread_rank()</code>、<code>num_threads()</code>等基础接口外，还支持shfl类和vote类接口，例如<code>shfl()</code>、<code>shfl_up()</code>、<code>shfl_down()</code>、<code>shfl_xor()</code>、<code>any()</code>、<code>all()</code>和<code>ballot()</code>。</p><h3 id="coalesced_group">coalesced_group<a class="header-anchor" href="#coalesced_group">​</a></h3><p>在SIMT架构的硬件层面上，处理器以32个线程为一组（一个Warp）来执行线程。当线程遇到条件分支时会出现发散，Warp会串行地执行每个分支，在执行某个分支时会屏蔽不在该指令路径上的线程。在路径上保持活跃的线程被称为合并线程（coalesced）。<code>coalesced_group</code>表示当前Warp内处于活跃状态并参与当前执行路径的线程集合，通过<code>coalesced_threads()</code>接口创建。它常用于条件分支中，仅让到达当前分支的活跃线程组成协作组。</p><p>示例代码中创建一个名为<code>active</code>的组，该组包含Warp中所有线程id为偶数的线程。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">%</span><span class="w"> </span><span class="mi">2</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">0</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">coalesced_group</span><span class="w"> </span><span class="n">active</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">coalesced_threads</span><span class="p">();</span>
<span class="w">    </span><span class="kt">unsigned</span><span class="w"> </span><span class="kt">int</span><span class="w"> </span><span class="n">rank</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">active</span><span class="p">.</span><span class="n">thread_rank</span><span class="p">();</span>
<span class="w">    </span><span class="p">...</span>
<span class="p">}</span>
</code></pre></div><p>通过<code>coalesced_threads()</code>创建的<code>coalesced_group</code>对象表示的是在当前时刻处于活跃状态的线程集合。其组内包含哪些线程由<code>coalesced_threads()</code>接口调用的位置决定，并且不随后续代码执行变化，也不保证这些线程在整个执行过程中持续保持活跃。</p><h2 id="组划分">组划分<a class="header-anchor" href="#组划分">​</a></h2><p>协作组支持将父组划分为更小的子组。当前提供以下划分接口：</p><ul><li><a href="../../../api/SIMT-API/cooperative_groups/tiled_partition.html">tiled_partition</a>：将父组划分为指定大小的子组。</li><li><a href="../../../api/SIMT-API/cooperative_groups/binary_partition.html">binary_partition</a>：根据布尔标签将父组划分为两个<code>coalesced_group</code>子组。</li></ul><h3 id="tiled_partition">tiled_partition<a class="header-anchor" href="#tiled_partition">​</a></h3><p><code>tiled_partition</code>用于按固定大小划分父组。模板版本在编译期指定子组大小，并返回<code>thread_block_tile</code>对象。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">using</span><span class="w"> </span><span class="k">namespace</span><span class="w"> </span><span class="nn">cooperative_groups</span><span class="p">;</span>

<span class="n">__global__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">simt_kernel</span><span class="p">(...)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">thread_block</span><span class="w"> </span><span class="n">block</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">this_thread_block</span><span class="p">();</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">tile8</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">tiled_partition</span><span class="o">&lt;</span><span class="mi">8</span><span class="o">&gt;</span><span class="p">(</span><span class="n">block</span><span class="p">);</span>

<span class="w">    </span><span class="kt">unsigned</span><span class="w"> </span><span class="kt">int</span><span class="w"> </span><span class="n">lane</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">tile8</span><span class="p">.</span><span class="n">thread_rank</span><span class="p">();</span>
<span class="w">    </span><span class="p">...</span>
<span class="p">}</span>
</code></pre></div><p>模板版本的划分大小必须满足<code>tiled_partition</code>接口约束，详细要求请参考<a href="../../../api/SIMT-API/cooperative_groups/tiled_partition.html">tiled_partition</a>。</p><h3 id="binary_partition">binary_partition<a class="header-anchor" href="#binary_partition">​</a></h3><p><code>binary_partition</code>用于按照布尔条件将<code>coalesced_group</code>或<code>thread_block_tile</code>划分为两个子组。条件值相同的线程会进入同一子组。</p><p>示例代码将一个包含32个线程的<code>thread_block_tile</code>划分为奇数组和偶数组。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">using</span><span class="w"> </span><span class="k">namespace</span><span class="w"> </span><span class="nn">cooperative_groups</span><span class="p">;</span>

<span class="n">__global__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">simt_kernel</span><span class="p">(</span><span class="kt">int</span><span class="w"> </span><span class="o">*</span><span class="n">input_arr</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">thread_block</span><span class="w"> </span><span class="n">block</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">this_thread_block</span><span class="p">();</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">tile32</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">tiled_partition</span><span class="o">&lt;</span><span class="mi">32</span><span class="o">&gt;</span><span class="p">(</span><span class="n">block</span><span class="p">);</span>

<span class="w">    </span><span class="c1">// input_arr中是随机整数</span>
<span class="w">    </span><span class="kt">int</span><span class="w"> </span><span class="n">elem</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">input_arr</span><span class="p">[</span><span class="n">block</span><span class="p">.</span><span class="n">thread_rank</span><span class="p">()];</span>
<span class="w">    </span><span class="n">coalesced_group</span><span class="w"> </span><span class="n">subgroup</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">binary_partition</span><span class="p">(</span><span class="n">tile32</span><span class="p">,</span><span class="w"> </span><span class="p">(</span><span class="n">elem</span><span class="w"> </span><span class="o">&amp;</span><span class="w"> </span><span class="mi">1</span><span class="p">));</span>

<span class="w">    </span><span class="kt">unsigned</span><span class="w"> </span><span class="kt">int</span><span class="w"> </span><span class="n">rank</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">subgroup</span><span class="p">.</span><span class="n">thread_rank</span><span class="p">();</span>
<span class="w">    </span><span class="p">...</span>
<span class="p">}</span>
</code></pre></div><h2 id="注意事项">注意事项<a class="header-anchor" href="#注意事项">​</a></h2><p>协作组中的同步和通信接口一般要求组内相关线程共同参与调用。常见接口包括：</p><ul><li><code>sync()</code>：同步组内线程。</li><li><code>shfl()</code>、<code>shfl_up()</code>、<code>shfl_down()</code>、<code>shfl_xor()</code>：在组内线程之间交换寄存器数据。</li><li><code>any()</code>、<code>all()</code>：对组内线程的输入进行投票判断。<code>any()</code>在组内任一线程的输入非0时返回真，<code>all()</code>在组内所有线程的输入均非0时返回真。</li><li><code>ballot()</code>：将组内各线程的输入汇聚为一个位掩码返回，输入非0的线程在掩码中对应比特位为1。</li></ul><p>调用这些接口时，需要保证参与操作的线程集合与组句柄描述的线程集合一致。若只有部分组内线程到达同步点，或者不同线程以不一致的控制流调用同一个集体操作，可能导致结果不正确或程序卡死。</p><div data-filter="950"><p>Ascend 950PR/Ascend 950DT SIMT架构不支持独立线程调度。一个Warp内的多个协作组之间应避免存在相互等待或数据依赖，否则可能导致卡死。</p></div></article></div>`,1)])])}const v=a(e,[["render",o]]);export{g as __pageData,v as default};
